-- Endereço dos condomínios (3º arquivo do usuário, 2026-11-10): logradouro,
-- bairro e CEP de cada mural já cadastrado. Endereço de CONDOMÍNIO (dado
-- público do prédio), não de morador. Corrige também a cidade do Duetto
-- Damebe (Mogi das Cruzes; o rodapé do mural dizia São Paulo). Idempotente.
ALTER TABLE public.oportunidade_fontes ADD COLUMN IF NOT EXISTS endereco text CHECK (char_length(endereco) <= 160);
ALTER TABLE public.oportunidade_fontes ADD COLUMN IF NOT EXISTS cep text CHECK (char_length(cep) <= 9);

